const pages = $input.first().json.results;
if (!Array.isArray(pages)) throw new Error('Notion não devolveu results[]. Falhar fechado.');
const plain = p => {
  if (!p) return '';
  if (p.type === 'status') return p.status?.name ?? '';
  if (p.type === 'select') return p.select?.name ?? '';
  if (p.type === 'url') return p.url ?? '';
  if (p.type === 'title') return (p.title ?? []).map(x => x.plain_text ?? x.text?.content ?? '').join('');
  if (p.type === 'rich_text') return (p.rich_text ?? []).map(x => x.plain_text ?? x.text?.content ?? '').join('');
  return '';
};
const eligible = [], blocked = [], pending = [], rejected = [];
for (const page of pages) {
  const p = page.properties ?? {};
  const row = {
    notion_id: page.id, briefing: plain(p['Briefing']), status: plain(p['Status']),
    projeto: plain(p['Projeto']), objetivo: plain(p['Objetivo']),
    prioridade: plain(p['Prioridade']), criterios: plain(p['Critérios de aceite']),
    repositorio: plain(p['Repositório']), issue_github: plain(p['Issue GitHub']),
    edited_at: page.last_edited_time
  };
  if (row.status === 'Rejeitado') { rejected.push(row); continue; }
  if (row.status !== 'Aprovado') { pending.push(row); continue; }
  const required = ['briefing','projeto','objetivo','criterios','repositorio'];
  const missing = required.filter(k => !row[k]);
  if (missing.length) { blocked.push({...row,motivo:'Campos obrigatórios ausentes: '+missing.join(', ')}); continue; }
  if (row.repositorio !== 'https://github.com/Ceistutis/AI-Development-Studio') {
    blocked.push({...row,motivo:'Repositório diferente do autorizado para este MVP'}); continue;
  }
  if (row.issue_github) { blocked.push({...row,motivo:'Issue GitHub já preenchida'}); continue; }
  eligible.push(row);
}
return [{json:{eligible,blocked,pending,rejected,counts:{eligible:eligible.length,blocked:blocked.length,pending:pending.length,rejected:rejected.length},mode:'DRY_RUN_NO_WRITES'}}];

const searched = $input.all();
const original = $('Separar elegíveis').all();
return searched.map((item,i)=>{
  const b = original[i]?.json;
  if (!b) throw new Error('Falha em correlacionar resultados GitHub com briefings; não avançar.');
  const payload=item.json;
  if (!Array.isArray(payload.items) || typeof payload.total_count !== 'number') throw new Error('Resposta inesperada do GitHub.');
  const matches=payload.items.filter(x => !x.pull_request && (x.body??'').includes('NOTION_BRIEFING_ID:'+b.notion_id));
  return {json:{
    mode:'DRY_RUN_NO_WRITES',notion_id:b.notion_id,briefing:b.briefing,
    github_matches:matches.map(x=>({number:x.number,url:x.html_url})),
    decision:matches.length?'BLOQUEADO_ISSUE_EXISTENTE':'SIMULACAO_PRONTA',
    warning:'Busca por marcador não garante idempotência concorrente; não ativar escrita sem lock/deduplicação.',
    proposed_issue:{
      title:'[ADS] '+b.briefing,
      body:'Projeto: '+b.projeto+'\\nObjetivo: '+b.objetivo+'\\nCritérios de aceite: '+b.criterios+'\\n\\nNOTION_BRIEFING_ID:'+b.notion_id
    }
  }};
});
